{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people with refreshment settings and accessible entertainment control.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Provides a drink and food vessel for one person",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "plate"],
        "required_properties": ["holds liquid", "holds food"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Operates the television",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote"],
        "required_properties": ["controls television"]
      },
      {
        "id": "surface",
        "entity_kind": "REGION",
        "function": "Supports objects and provides a stable platform",
        "required_count": 3,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk"],
        "required_properties": ["flat", "horizontal"]
      },
      {
        "id": "seating_area",
        "entity_kind": "FIXED_TARGET",
        "function": "Reference point for 'nearby' and accessibility",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": ["chair"],
        "required_properties": ["upright", "for sitting"]
      }
    ],
    "functional_relations": [
      {
        "id": "setting_near_seat",
        "relation": "refreshment_setting is placed near seating_area",
        "participant_roles": ["refreshment_setting", "seating_area"]
      ,
      "required": true
      },
      {
        "id": "control_accessible",
        "relation": "entertainment_control is placed accessible to seating_area",
        "participant_roles": ["entertainment_control", "seating_area"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "arrange_refreshments",
        "operation": "Place refreshment_setting on surface",
        "participant_roles": ["refreshment_setting", "surface"]
      ,
      "operation_count": 2
      },
      {
        "id": "position_control",
        "operation": "Place entertainment_control on surface",
        "participant_roles": ["entertainment_control", "surface"]
      ,
      "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {"label": "red cup", "visual_description": "on coffee table"},
        {"label": "white plate", "visual_description": "on left side table"},
        {"label": "red cup", "visual_description": "on right desk"},
        {"label": "white plate", "visual_description": "on right desk"}
      ],
      "entertainment_control": [
        {"label": "black remote", "visual_description": "on right desk"}
      ],
      "surface": [
        {"label": "coffee table", "visual_description": "central table"},
        {"label": "left side table", "visual_description": "next to left chair"},
        {"label": "right desk", "visual_description": "large desk on right"},
        {"label": "bench", "visual_description": "under TV"}
      ],
      "seating_area": [
        {"label": "left chair", "visual_description": "wooden chair with black cushion"},
        {"label": "right chair", "visual_description": "wooden chair with black cushion"}
      ]
    },
    "inspectable_regions": [
      {
        "id": "desk_drawers",
        "label": "drawers in the large desk",
        "visual_description": "front panel of the large desk on the right",
        "reason": "closed storage structure that might contain additional controls or supplies"
      }
    ],
    "inspection_order": [
      "desk_drawers"
    ]
  }
